solution.code:
function buatApp() {
  let tumpukan = ["beranda"];
  const data = {};
  const antrean = [];
  const menyerah = [];
  let nomor = 0;
  const buka = (layar) => {
    tumpukan = [...tumpukan, layar];
  };
  return {
    buka,
    kembali() {
      if (tumpukan.length === 1) return false;
      tumpukan = tumpukan.slice(0, -1);
      return true;
    },
    ganti(layar) {
      tumpukan = [...tumpukan.slice(0, -1), layar];
    },
    layar() {
      return tumpukan[tumpukan.length - 1];
    },
    tumpukan() {
      return [...tumpukan];
    },
    tautan(url) {
      const bagian = url.split("?")[0].split("://")[1] || "";
      const s = bagian.split("/");
      if (s.length !== 2 || s[0] !== "kelas" || !/^[0-9]+$/.test(s[1])) return false;
      buka(`kelas:${s[1]}`);
      return true;
    },
    ubah(id, nilai) {
      nomor += 1;
      const aksiId = `a${nomor}`;
      antrean.push({ aksiId, kunci: id, nilai, sebelumnya: data[id], coba: 0 });
      data[id] = nilai;
      return aksiId;
    },
    terkirim(aksiId) {
      const i = antrean.findIndex((a) => a.aksiId === aksiId);
      if (i !== -1) antrean.splice(i, 1);
    },
    gagal(aksiId) {
      const i = antrean.findIndex((a) => a.aksiId === aksiId);
      if (i === -1) return "tidak ada";
      const a = antrean[i];
      a.coba += 1;
      if (a.coba < 3) return "ulang";
      if (a.sebelumnya === undefined) delete data[a.kunci];
      else data[a.kunci] = a.sebelumnya;
      antrean.splice(i, 1);
      menyerah.push(aksiId);
      return "menyerah";
    },
    data() {
      return { ...data };
    },
    antrean() {
      return antrean.length;
    },
    menyerah() {
      return [...menyerah];
    },
  };
}

